question.answer:
def alpha_beta(arbre):
    compteur = [0]

    def explorer(noeud, alpha, beta, maximisant):
        if not isinstance(noeud, list):
            compteur[0] += 1
            return noeud
        if maximisant:
            valeur = float('-inf')
            for fils in noeud:
                valeur = max(valeur, explorer(fils, alpha, beta, False))
                alpha = max(alpha, valeur)
                if alpha >= beta:
                    break
            return valeur
        valeur = float('inf')
        for fils in noeud:
            valeur = min(valeur, explorer(fils, alpha, beta, True))
            beta = min(beta, valeur)
            if alpha >= beta:
                break
        return valeur

    v = explorer(arbre, float('-inf'), float('inf'), True)
    return (v, compteur[0])

