LIGNES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def gagnant(g):
    for a, b, c in LIGNES:
        if g[a] != '.' and g[a] == g[b] == g[c]:
            return g[a]
    return None

def valeur(g, joueur):
    v = gagnant(g)
    if v == 'X':
        return 1
    if v == 'O':
        return -1
    if '.' not in g:
        return 0
    scores = []
    for i in range(9):
        if g[i] == '.':
            suite = g[:i] + joueur + g[i+1:]
            scores.append(valeur(suite, 'O' if joueur == 'X' else 'X'))
    return max(scores) if joueur == 'X' else min(scores)

def meilleur_coup(grille, joueur):
    if gagnant(grille) is not None or '.' not in grille:
        return -1
    autre = 'O' if joueur == 'X' else 'X'
    meilleur, indice = None, -1
    for i in range(9):
        if grille[i] != '.':
            continue
        v = valeur(grille[:i] + joueur + grille[i+1:], autre)
        if meilleur is None or (joueur == 'X' and v > meilleur) or (joueur == 'O' and v < meilleur):
            meilleur, indice = v, i
    return indice

from math import log, sqrt

def choisir(stats, c=1.0):
    total = sum(n for _, n in stats)
    for i, (v, n) in enumerate(stats):
        if n == 0:
            return i
    meilleur, indice = None, -1
    for i, (v, n) in enumerate(stats):
        score = v / n + c * sqrt(log(total) / n)
        if meilleur is None or score > meilleur:
            meilleur, indice = score, i
    return indice

def coup_final(stats):
    meilleur, indice = -1, -1
    for i, (v, n) in enumerate(stats):
        if n > meilleur:
            meilleur, indice = n, i
    return indice
